const state={token:sessionStorage.kivraToken||'',user:JSON.parse(sessionStorage.kivraUser||'null'),items:[],printers:[],allPrinters:[],locations:[],allLocations:[],categories:[],labels:[],expiry:[],users:[],bridgeDevices:[],bridgePairing:null,userFormOpen:false,printerCandidates:[],printerNetworks:[],usbQueues:[],view:'home',selected:null,selectedLabel:null,category:null,result:null,editingPrinter:null,editingItem:null,itemImageDraft:undefined,prefillCategoryId:'',itemReturnCategory:null,selectedLocation:null,storageGroup:'Chillers',previewStorage:null,previewPrinter:null,defaultPrinterId:localStorage.kivraDefaultPrinterId||'',busy:false,dataError:null};
function newIdempotencyKey(){if(globalThis.crypto?.randomUUID)return globalThis.crypto.randomUUID();const bytes=new Uint8Array(16);if(globalThis.crypto?.getRandomValues)globalThis.crypto.getRandomValues(bytes);else for(let i=0;i<bytes.length;i++)bytes[i]=Math.floor(Math.random()*256);bytes[6]=(bytes[6]&15)|64;bytes[8]=(bytes[8]&63)|128;const hex=[...bytes].map(value=>value.toString(16).padStart(2,'0')).join('');return`${hex.slice(0,8)}-${hex.slice(8,12)}-${hex.slice(12,16)}-${hex.slice(16,20)}-${hex.slice(20)}`}
const app=document.querySelector('#app');
const defaultPrinterObserver=new MutationObserver(()=>{const select=document.querySelector('#printerSelect');if(!select||select.dataset.defaultReady)return;const preferred=preferredPrinter();if(preferred)select.value=preferred.id;select.dataset.defaultReady='true'});
defaultPrinterObserver.observe(app,{childList:true,subtree:true});
