const categoryPresets=[
 {name:'Prepared Food',icon:'🍲',tone:'amber'}, {name:'Cut Vegetables',icon:'🥬',tone:'green'},
 {name:'Gravy/Base',icon:'🥘',tone:'orange'}, {name:'Sauces',icon:'🫙',tone:'red'},
 {name:'Dry Stock',icon:'🌾',tone:'sand'}, {name:'Frozen Items',icon:'🧊',tone:'blue'},
 {name:'Raw Meat',icon:'🍗',tone:'rose'}, {name:'Seafood',icon:'🦐',tone:'aqua'},
 {name:'Dairy',icon:'🥛',tone:'yellow'}, {name:'Spices',icon:'🌶️',tone:'purple'},
 {name:'Others',icon:'•••',tone:'grey'}, {name:'General',icon:'◇',tone:'purple'}
];
const categoryImageFor=name=>{const n=(name||'').toLowerCase();if(n.includes('prepared'))return'https://images.unsplash.com/photo-1601050690597-df0568f70950?auto=format&fit=crop&w=700&q=82';if(n.includes('vegetable'))return'https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=700&q=82';if(n.includes('gravy')||n.includes('base'))return'https://images.unsplash.com/photo-1603894584373-5ac82b2ae398?auto=format&fit=crop&w=700&q=82';if(n.includes('sauce'))return'https://images.unsplash.com/photo-1472476443507-c7a5948772fc?auto=format&fit=crop&w=700&q=82';if(n.includes('dry'))return'https://images.unsplash.com/photo-1586201375761-83865001e31c?auto=format&fit=crop&w=700&q=82';if(n.includes('frozen'))return'https://images.unsplash.com/photo-1498579397066-22750a3cb424?auto=format&fit=crop&w=700&q=82';if(n.includes('raw meat'))return'https://images.unsplash.com/photo-1604503468506-a8da13d82791?auto=format&fit=crop&w=700&q=82';if(n.includes('seafood'))return'https://images.unsplash.com/photo-1565680018434-b513d5e5fd47?auto=format&fit=crop&w=700&q=82';if(n.includes('dairy'))return'https://images.unsplash.com/photo-1628088062854-d1870b4553da?auto=format&fit=crop&w=700&q=82';if(n.includes('spice'))return'https://images.unsplash.com/photo-1596040033229-a9821ebd058d?auto=format&fit=crop&w=700&q=82';if(n.includes('general'))return'https://images.unsplash.com/photo-1532336414038-cf19250c5757?auto=format&fit=crop&w=700&q=82';return'https://images.unsplash.com/photo-1509358271058-acd22cc93898?auto=format&fit=crop&w=700&q=82'};
const categoryStyle=name=>` style="background-image:url('${categoryImageFor(name)}');background-size:cover"`;
const iconFor=name=>{const n=(name||'').toLowerCase();if(n.includes('onion'))return'🧅';if(n.includes('capsicum'))return'🫑';if(n.includes('carrot'))return'🥕';if(n.includes('chicken'))return'🍗';if(n.includes('prawn')||n.includes('fish'))return'🦐';if(n.includes('sauce')||n.includes('mayo'))return'🫙';if(n.includes('flour')||n.includes('maida'))return'🌾';if(n.includes('gravy'))return'🥘';return'🥣'};
const photoFor=name=>{const n=(name||'').toLowerCase();if(n.includes('onion'))return'photo-6';if(n.includes('flour')||n.includes('maida')||n.includes('dry'))return'photo-4';if(n.includes('frozen')||n.includes('ice'))return'photo-5';if(n.includes('sauce')||n.includes('mayo')||n.includes('ketchup'))return'photo-3';if(n.includes('gravy')||n.includes('base'))return'photo-2';if(n.includes('raw meat')||n.includes('raw chicken'))return'photo-7';if(n.includes('vegetable')||n.includes('capsicum')||n.includes('carrot')||n.includes('cabbage')||n.includes('broccoli')||n.includes('bean')||n.includes('tomato'))return'photo-1';return'photo-0'};
const photoClass=x=>x?.imageDataUrl?'custom-photo':photoFor(x?.name);
const photoStyle=x=>x?.imageDataUrl?` style="background-image:url('${x.imageDataUrl}')"`:'';
const classificationLabel=value=>value==='NonVeg'?'NON-VEG':value==='Veg'?'VEG':value==='Egg'?'EGG':'OTHER';
const classificationMark=value=>value==='Veg'?'<span class="food-mark veg" aria-hidden="true"><i></i></span>':value==='NonVeg'?'<span class="food-mark non-veg" aria-hidden="true"><i></i></span>':'';
const classificationClass=value=>value==='NonVeg'?'non-veg':value==='Veg'?'veg':'other';
const categoryKey=name=>String(name||'').trim().toLowerCase().replace(/[^a-z0-9]/g,'').replace(/^other$/,'others');
const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const dt=(value,options={})=>new Intl.DateTimeFormat('en-IN',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',...options}).format(new Date(value));
const time=value=>new Intl.DateTimeFormat('en-IN',{hour:'2-digit',minute:'2-digit'}).format(new Date(value));
const date=value=>new Intl.DateTimeFormat('en-IN',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(value));
const operationalNow=()=>{const d=new Date();if(d.getHours()<2)d.setDate(d.getDate()-1);return d};
const relative=value=>{const ms=new Date(value)-Date.now(),m=Math.round(Math.abs(ms)/60000);if(ms<0)return'Expired';if(m<60)return`${m}m`;const h=Math.floor(m/60),rm=m%60;return h<24?`${h}h ${rm}m`:`${Math.ceil(h/24)}d`};
async function request(path,options={}){const headers={...(options.body?{'content-type':'application/json'}:{}),...(state.token?{Authorization:`Bearer ${state.token}`}:{})};const r=await fetch(path,{...options,headers:{...headers,...options.headers}});if(r.status===401&&path!=='/api/auth/pin'){signOut();throw Error('Your session expired. Please sign in again.')}const text=await r.text();let body=text;try{body=text?JSON.parse(text):null}catch{}const validationMessage=body?.errors&&Object.values(body.errors).flat()[0];if(!r.ok)throw Error(r.status===401?'Incorrect PIN. Please try again.':validationMessage||body?.detail||body?.title||body||'Request failed');return body}
function preferredPrinter(){return state.printers.find(p=>p.id===state.defaultPrinterId)||state.printers.find(p=>p.driver!=='Fake')||state.printers[0]||null}
function rememberPrinter(id){if(!id)return;state.defaultPrinterId=id;localStorage.kivraDefaultPrinterId=id}
function applyBootstrap(data){state.items=data.items||[];state.printers=data.printers||[];state.locations=data.locations||[];state.labels=data.labels||[];state.expiry=data.expiry||[];state.categories=data.categories||[];state.allPrinters=data.allPrinters||[];state.allLocations=data.allLocations||[];state.users=data.users||[];const selected=state.printers.find(p=>p.id===state.defaultPrinterId),physical=state.printers.find(p=>p.driver!=='Fake');if(!selected||(selected.driver==='Fake'&&physical)){const fallback=physical||state.printers[0];if(fallback)rememberPrinter(fallback.id);else{state.defaultPrinterId='';localStorage.removeItem('kivraDefaultPrinterId')}}}
function restoreBootstrap(){try{const cached=JSON.parse(sessionStorage.kivraBootstrap||'null');if(cached){applyBootstrap(cached);return true}}catch{sessionStorage.removeItem('kivraBootstrap')}return false}
async function hydrate(){const data=await request('/api/bootstrap');state.dataError=null;applyBootstrap(data);try{sessionStorage.kivraBootstrap=JSON.stringify(data)}catch{}render()}
function brandLogo(className='brand-logo'){return`<img class="${className}" src="/assets/kivra-routes-logo.webp" alt="KIVRA by Routes">`}
