function topbar(title,back=false,dark=false){return`<header class="topbar ${dark?'dark':''}">${back?`<button class="icon-btn" data-action="back" aria-label="Back">‹</button>`:`<div class="brand-lockup">${brandLogo()}</div>`}<h1>${esc(title||'')}</h1><button class="icon-btn" data-action="notifications" aria-label="Notifications">♢</button></header>`}
function bottom(active){const desktop=matchMedia('(min-width:760px)').matches,p=preferredPrinter(),desktopBrand=desktop?`<button type="button" class="nav-brand" data-view="home" aria-label="Go to home"><span class="sidebar-wordmark"><b>KIVR<i>▲</i></b><small><em>R</em> Routes</small></span></button>`:'',printer=desktop?`<button type="button" class="sidebar-printer" data-view="more"><i aria-hidden="true">▣</i><span><b>${esc(p?.name||'Kitchen Printer')}</b><small><em class="online-dot ${p?'':'off'}"></em>${p?'Online':'Setup needed'}</small><small>${p?.ipAddress?`IP: ${esc(p.ipAddress)}`:esc(p?.model||'No printer configured')}</small></span><strong aria-hidden="true">›</strong></button>`:'';return`<nav class="bottom-nav" aria-label="Primary navigation">${desktopBrand}${[['home','⌂','Home'],['expiry','◇','Labels'],['history','◷','History'],['items','⬡','Items'],['more','⚙','Settings']].map(([v,i,l])=>`<button class="${active===v?'active':''}" data-view="${v}" ${active===v?'aria-current="page"':''}><i aria-hidden="true">${i}</i><span>${l}</span></button>`).join('')}${printer}</nav>`}
function page(content,active='home',opts={}){if(['Manage Items','Edit Item','Add Item'].includes(opts.title))active='items';return`${topbar(opts.title,opts.back,opts.dark)}<main class="screen ${opts.className||''}">${content}</main>${bottom(active)}`}
function workspaceNav(active){return`<nav class="workspace-nav" aria-label="Primary navigation"><button type="button" class="workspace-brand" data-view="home" aria-label="KIVRA Routes home">${brandLogo('workspace-logo')}</button><div class="workspace-links">${[['home','Home'],['items','Items'],['expiry','Labels'],['history','History'],['more','Settings']].map(([v,l])=>`<button type="button" class="workspace-link ${active===v?'active':''}" data-view="${v}" ${active===v?'aria-current="page"':''}><i aria-hidden="true">${navIcons[v]}</i><span>${l}</span></button>`).join('')}</div><button type="button" class="workspace-print" data-action="test-print"><span aria-hidden="true">▣</span> Test Print</button></nav>`}
function bottom(active){const desktop=matchMedia('(min-width:760px)').matches,p=preferredPrinter(),desktopBrand=desktop?`<button type="button" class="nav-brand" data-view="home" aria-label="Go to home">${brandLogo('nav-brand-logo')}</button>`:'',printer=desktop?`<button type="button" class="sidebar-printer" data-view="more"><i aria-hidden="true">▣</i><span><b>${esc(p?.name||'Kitchen Printer')}</b><small><em class="online-dot ${p?'':'off'}"></em>${p?'Online':'Setup needed'}</small><small>${p?.ipAddress?`IP: ${esc(p.ipAddress)}`:esc(p?.model||'No printer configured')}</small></span><strong aria-hidden="true">›</strong></button>`:'';return`<nav class="bottom-nav" aria-label="Primary navigation">${desktopBrand}${[['home','Home'],['expiry','Labels'],['history','History'],['items','Items'],['more','Settings']].map(([v,l])=>`<button type="button" class="${active===v?'active':''}" data-view="${v}" ${active===v?'aria-current="page"':''}><i aria-hidden="true">${navIcons[v]}</i><span>${l}</span></button>`).join('')}${printer}</nav>`}
function page(content,active='home',opts={}){const resolvedActive=/Item/.test(opts.title||'')?'items':active;return`${workspaceNav(resolvedActive)}${topbar(opts.title,opts.back,opts.dark)}<main class="screen ${opts.className||''}">${content}</main>${bottom(resolvedActive)}`}
function printerCard(link=false){const p=preferredPrinter();return`<div class="printer-card" ${link?'data-view="printers" role="button" tabindex="0"':''}><span class="status-orb ${p?'':'off'}"></span><div><b>${esc(p?.name||'Kitchen Printer')}</b><small><span class="online-dot ${p?'':'off'}"></span> ${p?'Default printer':'Not configured'}</small><small>${esc(p?.model||'Add printer in Settings')}${p?.ipAddress?` · ${esc(p.ipAddress)}`:''}</small></div><span class="chevron">›</span></div>`}
function categoryExpiryCount(name){const itemNames=new Set(state.items.filter(x=>categoryKey(x.category)===categoryKey(name)).map(x=>x.name.toLowerCase()));return state.expiry.filter(x=>itemNames.has((x.itemName||'').toLowerCase())).length}
function home(){const recent=state.labels.slice(0,5),greeting=new Date().getHours()<12?'Good morning':new Date().getHours()<17?'Good afternoon':'Good evening',names=state.categories.map(x=>x.name),merged=[...categoryPresets,...names.map((name,i)=>({...categoryPresets[i%categoryPresets.length],name}))],seen=new Set(),available=merged.filter(x=>{const k=categoryKey(x.name);if(seen.has(k))return false;seen.add(k);return true});return page(`<section class="home-hero"><div class="home-commandbar"><label class="search"><span>⌕</span><input id="homeSearch" placeholder="Search for food items, ingredients, or categories…" autocomplete="off"></label></div><div class="welcome-banner"><div class="greeting"><h2>${greeting}!</h2><p>Quickly find items and print labels for your kitchen.</p></div><div class="welcome-tip"><span aria-hidden="true">☼</span><div><b>Tip</b><small>Search by item name, category or ingredient to print labels faster.</small></div></div></div><div class="category-section-heading"><div><span aria-hidden="true">▦</span><h2>Categories</h2></div><button data-view="items">View all categories&nbsp; →</button></div><div class="category-grid">${available.map(c=>{const total=countCategory(c.name),expiring=categoryExpiryCount(c.name);return`<button class="category-card photo-card ${c.tone}"${categoryStyle(c.name)} data-category="${esc(c.name)}"><span class="category-icon" aria-hidden="true">${c.icon||'▦'}</span><b>${esc(c.name)}</b><span class="category-counts"><small>${total} item${total===1?'':'s'}</small><small class="category-expiry ${expiring?'has-expiry':''}">${expiring} expiring</small></span><i aria-hidden="true">›</i></button>`}).join('')}${state.user?.role==='Administrator'?'<button class="add-category-card" data-view="items"><span>+</span><b>Add New Category</b><small>Create and manage categories</small></button>':''}</div></section><section class="content-section recent-section"><div class="section-heading recent-heading"><div><h2>◷&nbsp; Recently Printed</h2><p>Jump back into your latest label activity</p></div>${recent.length?'<button data-view="history">View all history&nbsp; →</button>':''}</div><div class="recent-list ${recent.length?'':'is-empty'}">${recent.length?recent.map(recentRow).join(''):`<div class="empty"><span aria-hidden="true">▤</span><b>No labels printed yet</b><small>Your latest labels will appear here after your first print.</small></div>`}</div></section>`, 'home',{dark:true,className:'home-screen'})}
function countCategory(name){return state.items.filter(x=>categoryKey(x.category)===categoryKey(name)).length}
function labelRow(x){return`<button class="list-row" data-label="${x.id}"><span class="food-thumb food-photo ${photoFor(x.itemName)}"></span><span class="row-copy"><b>${esc(x.itemName)}</b><small>${esc(x.storageLocation)} · ${esc(x.labelCode)}</small></span><span class="row-meta"><b>${x.lastPrintStatus==='Printed'?'Printed':esc(x.status)}</b><small>${time(x.expiryDateTime)}</small></span></button>`}
function recentRow(x){const item=state.items.find(i=>i.name.toLowerCase()===x.itemName.toLowerCase()),photo=item||{name:x.itemName};return`<button class="list-row recent-row" ${item?`data-item="${item.id}"`:''}><span class="food-thumb food-photo ${photoClass(photo)}"${photoStyle(photo)}></span><span class="row-copy"><b>${esc(x.itemName)}</b><small><span class="recent-status-dot" aria-hidden="true"></span> Printed ${date(x.createdAt||x.operationalDateTime)} at ${time(x.createdAt||x.operationalDateTime)}</small></span>${item?'<span class="quick-print"><span aria-hidden="true">▣</span> Print again</span>':'<span class="recent-chevron" aria-hidden="true">›</span>'}</button>`}
function categoryView(){const filtered=state.category?state.items.filter(x=>categoryKey(x.category)===categoryKey(state.category)):state.items,title=state.category||'All items',canAdd=state.user?.role==='Administrator'&&state.category;return page(`<div class="category-page"><div class="category-heading"><button class="icon-btn category-back" data-action="back" aria-label="Back">‹</button><div><h1>${esc(title)}</h1><p>${filtered.length} item${filtered.length===1?'':'s'} available to print</p></div>${canAdd?`<button class="btn btn-primary category-add-item" data-action="add-item-to-category">+ Add item to ${esc(title)}</button>`:''}</div><label class="admin-search category-search"><span>⌕</span><input id="listSearch" placeholder="Search ${esc(title.toLowerCase())}" autocomplete="off"></label><section class="category-list-shell"><div class="category-list-head"><span>Item</span><span>Storage</span><span>Shelf life</span><span></span></div><div id="itemList">${filtered.length?filtered.map(itemRow).join(''):`<div class="empty category-empty"><span aria-hidden="true">▤</span><b>No items in this category</b><small>${canAdd?'Use “Add item” above to create the first item here.':'No items are configured in this category yet.'}</small></div>`}</div></section></div>`, 'home',{title,back:true,className:'category-screen'})}
function itemRow(x){return`<button class="category-item-row" data-item="${x.id}"><span class="category-item-main"><span class="category-item-photo food-photo ${photoClass(x)}"${photoStyle(x)}></span><span><b>${esc(x.name)}</b><i class="class-badge ${classificationClass(x.classification)}">${classificationLabel(x.classification)}</i></span></span><span class="category-item-detail"><small>Storage</small><b>${esc(x.storage||'Not assigned')}</b></span><span class="category-item-detail"><small>Shelf life</small><b>${x.shelfLifeValue} ${esc(x.shelfLifeUnit)}</b></span><span class="category-item-open" aria-hidden="true">›</span></button>`}
function printView(){const x=state.selected;if(!x)return home();const now=operationalNow(),expiry=calculatePreview(now,x.shelfLifeValue,x.shelfLifeUnit);return page(`<div class="print-workspace"><button type="button" class="print-back" data-action="back"><span aria-hidden="true">‹</span> Back to items</button><section class="product-summary"><div class="food-visual photo-hero ${photoClass(x)}"${photoStyle(x)}></div><div class="product-heading"><div><h2>${esc(x.name)}</h2><p>${esc(x.category||'Kitchen item')}</p></div><i class="class-badge ${classificationClass(x.classification)}">${classificationLabel(x.classification)}</i></div><div class="date-summary"><div class="date-block"><span>${esc(x.dateTerminology||'PREPARED')}</span><b>${date(now)}</b><small>${time(now)}</small></div><div class="date-block expiry"><span>USE BY</span><b>${date(expiry)}</b><small>${time(expiry)}</small><i>${x.shelfLifeValue} ${esc(x.shelfLifeUnit)}</i></div></div></section><section class="print-controls"><header><small>Label setup</small><h2>Print settings</h2><p>Review the destination and quantity before printing.</p></header><div class="print-field-grid"><label class="field"><span>Storage location</span><select id="storageSelect">${storageOptions(x)}</select></label><label class="field"><span>Printer</span><select id="printerSelect">${state.printers.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label></div><div class="quantity-control"><span><b>Number of labels</b><small>Choose between 1 and 10 copies</small></span><div class="stepper"><button type="button" data-action="minus" aria-label="Decrease labels">−</button><output id="copies">1</output><button type="button" data-action="plus" aria-label="Increase labels">+</button></div></div><div class="print-actions"><button class="btn btn-primary" data-action="print">▣ <span>Print label</span></button><button class="btn btn-soft" data-action="preview">▤ <span>Preview</span></button></div></section></div>`, 'home',{title:x.name,back:true,className:'print-screen'})}
function calculatePreview(start,value,unit){const d=new Date(start);if(unit==='Minutes')d.setMinutes(d.getMinutes()+value);else if(unit==='Hours')d.setHours(d.getHours()+value);else if(unit==='Weeks')d.setDate(d.getDate()+value*7);else if(unit==='Months')d.setMonth(d.getMonth()+value);else d.setDate(d.getDate()+value);return d}
function storageOptions(x){if(state.locations.length)return state.locations.map(l=>`<option value="${l.id}" ${l.name===x.storage?'selected':''}>${esc(l.name)}</option>`).join('');return'<option value="" selected disabled>No active storage locations</option>'}
function previewLabel(code='RL-PREVIEW'){const x=state.selected,p=state.previewPrinter||preferredPrinter(),now=operationalNow(),expiry=calculatePreview(now,x?.shelfLifeValue||1,x?.shelfLifeUnit||'Days');return`<div class="label-paper" style="aspect-ratio:${p?.labelWidthMm||50}/${p?.labelHeightMm||30}"><b>${esc((x?.name||'KITCHEN ITEM').toUpperCase())}</b><small class="label-classification ${x?.classification==='Veg'?'veg':x?.classification==='NonVeg'?'non-veg':''}">${classificationMark(x?.classification)}<b>${classificationLabel(x?.classification)}</b></small><hr><div><strong>${esc((x?.dateTerminology||'PREPARED').toUpperCase())}</strong><span>${date(now).toUpperCase()}<br>${time(now)}</span></div><div><strong>USE BY</strong><span>${date(expiry).toUpperCase()}<br>${time(expiry)}</span></div><hr><footer><strong>${esc((state.previewStorage||document.querySelector('#storageSelect')?.selectedOptions[0]?.text||x?.storage||'STORAGE').toUpperCase())}</strong><strong>${esc(code)}</strong></footer></div>`}
function previewView(){const p=state.previewPrinter||preferredPrinter();return page(`<section class="preview-screen"><h2>Label Preview</h2><p>${p?.labelWidthMm||50} × ${p?.labelHeightMm||30} mm · ${p?.dpi||203} DPI</p>${previewLabel()}<button class="btn btn-primary btn-block" data-action="back-to-print">Back to print setup</button></section>`,'home',{title:'Preview Label',back:true})}
function successView(result){const queued=result.status==='Queued';return page(`<section class="success"><span class="success-check ${queued?'queued':''}">${queued?'✓':'✓'}</span><h2>${queued?'Label accepted':'Label printed'}</h2><p>${queued?'Sent to the local print bridge. Printing should begin immediately.':'Your label has been sent to the printer.'}</p>${previewLabel(result.labelCode)}<p class="success-copy">${queued?'Printing now':'Printed successfully'}<br><b>${esc(result.printerName||'Kitchen Printer')}</b></p><button class="btn btn-primary btn-block" data-action="print-another">Print Another</button><button class="btn btn-outline btn-block" data-view="home">Done</button></section>`, 'home',{dark:true})}
let expiryFilter='all';
function expiryGroups(){const now=new Date(),todayStart=new Date(now);todayStart.setHours(0,0,0,0);const tomorrowStart=new Date(todayStart),afterTomorrow=new Date(todayStart),afterNextThree=new Date(todayStart);tomorrowStart.setDate(tomorrowStart.getDate()+1);afterTomorrow.setDate(afterTomorrow.getDate()+2);afterNextThree.setDate(afterNextThree.getDate()+5);const active=x=>x.currentStatus!=='Expired'&&new Date(x.expiryDateTime)>=now;return{expired:state.expiry.filter(x=>x.currentStatus==='Expired'||new Date(x.expiryDateTime)<now),today:state.expiry.filter(x=>active(x)&&new Date(x.expiryDateTime)<tomorrowStart),tomorrow:state.expiry.filter(x=>active(x)&&new Date(x.expiryDateTime)>=tomorrowStart&&new Date(x.expiryDateTime)<afterTomorrow),next:state.expiry.filter(x=>active(x)&&new Date(x.expiryDateTime)>=afterTomorrow&&new Date(x.expiryDateTime)<afterNextThree)}}
function expiryView(){const groups=expiryGroups(),labels=expiryFilter==='all'?state.expiry:groups[expiryFilter]||[],titles={all:'Tracked labels',expired:'Expired labels',today:'Expiring today',tomorrow:'Expiring tomorrow',next:'Expiring in the next 3 days'},now=Date.now();const metric=(key,tone,label)=>`<button type="button" class="metric ${tone} ${expiryFilter===key?'selected':''}" data-expiry-filter="${key}"><b>${groups[key].length}</b><span>${label}</span></button>`;return page(`<div class="metric-grid">${metric('expired','danger','Expired')}${metric('today','warning','Expiring Today')}${metric('tomorrow','info','Tomorrow')}${metric('next','safe','Next 3 Days')}</div><div class="section-heading"><h2>${titles[expiryFilter]}</h2><button type="button" data-expiry-filter="all">${expiryFilter==='all'?'See history':'Show all'}</button></div><div class="expiry-list">${labels.length?labels.map(x=>`<button class="expiry-row ${x.currentStatus==='Expired'||new Date(x.expiryDateTime)<now?'urgent':'soon'}" data-label="${x.id}"><div><b>${esc(x.itemNameSnapshot)}</b><small>${esc(x.storageLocationSnapshot)}</small><small>Use by ${date(x.expiryDateTime)} · ${time(x.expiryDateTime)}</small></div><span>${relative(x.expiryDateTime)}</span></button>`).join(''):`<div class="empty tall"><span>✓</span><b>No labels in this group</b><small>Select another expiry card to view its labels.</small></div>`}</div>`, 'expiry',{title:'Expiry'})}
function historyView(){const hasHistory=state.labels.length>0;return page(`<div class="history-page"><div class="history-heading"><div><h1>Print History</h1><p>${hasHistory?`${state.labels.length} label record${state.labels.length===1?'':'s'}`:'Label activity and reprints'}</p></div>${hasHistory?`<label class="admin-search history-search"><span>⌕</span><input id="historySearch" placeholder="Search item, location or label code" autocomplete="off"></label>`:''}</div>${hasHistory?`<section class="history-ledger"><div class="history-table-head"><span>Printed</span><span>Item and storage</span><span>Label</span></div><div class="history-table" id="historyList">${state.labels.map(x=>`<button class="history-row" data-label="${x.id}"><span><small>${time(x.operationalDateTime)}</small></span><span><b>${esc(x.itemName)}</b><small>${esc(x.storageLocation)}</small></span><span><b>${esc(x.labelCode)}</b><small>${x.successfulPrintCount} print${x.successfulPrintCount===1?'':'s'}</small></span></button>`).join('')}</div></section>`:`<section class="history-empty"><span aria-hidden="true">▤</span><div><h2>No print history yet</h2><p>Printed labels will appear here automatically.</p></div><button class="btn btn-primary" data-view="home">Print a label</button></section>`}</div>`, 'history',{title:'Print History',className:'history-screen'})}
function labelDetailView(){const x=state.selectedLabel;if(!x)return historyView();const closed=['Consumed','Discarded','Cancelled'].includes(x.status);return page(`<div class="simple-page label-detail"><section class="settings-card"><h3>${esc(x.itemName)}</h3><div class="detail-grid"><span>Label code</span><b>${esc(x.labelCode)}</b><span>Prepared / opened</span><b>${dt(x.operationalDateTime)}</b><span>Use by</span><b>${dt(x.expiryDateTime)}</b><span>Storage</span><b>${esc(x.storageLocation)}</b><span>Status</span><b>${esc(x.status)}</b></div></section><section class="settings-card timeline"><h3>Timeline</h3><div><i>✓</i><span><b>Created</b><small>${dt(x.createdAt||x.operationalDateTime)}</small></span></div><div><i>▣</i><span><b>${x.successfulPrintCount>1?'Reprinted':'Printed'}</b><small>${x.successfulPrintCount} successful print${x.successfulPrintCount===1?'':'s'}</small></span></div><div><i>●</i><span><b>Current status: ${esc(x.status)}</b><small>${closed?'This label is closed.':'History is retained when status changes.'}</small></span></div></section><button class="btn btn-primary btn-block" data-action="reprint-label">Reprint Existing Label</button>${closed?'':`<div class="status-actions"><button class="btn btn-soft" data-label-status="Consumed">Mark Consumed</button><button class="btn btn-outline" data-label-status="Discarded">Mark Discarded</button></div>`}</div>`,'history',{title:x.labelCode,back:true})}
function moreView(){return page(`<div class="settings-page"><div class="settings-grid"><section class="settings-panel printer-panel"><div class="panel-heading"><div><small>Output device</small><h2>Printer</h2></div><span class="panel-status ${state.printers.length?'online':'offline'}">${state.printers.length?'Ready':'Setup needed'}</span></div>${printerCard(true)}<div class="panel-actions"><button class="btn btn-outline" data-action="test-print">Test Print</button><button class="btn btn-soft" data-view="printers">Printer Setup</button></div></section><section class="settings-panel application-panel"><div class="panel-heading"><div><small>Workspace</small><h2>Application</h2></div></div>${[['items','▤','Manage Items','Food rules and shelf life'],['storage','❄','Storage Locations','Chillers, freezers and dry store'],['users','♙','Users','Access and kitchen roles'],['bridge','⌁','Print Bridge','Windows USB or Android network printing'],['reports','⇩','Reports & CSV','Label history export'],['about','ⓘ','About KIVRA','Version and system details']].map(([v,i,l,d])=>`<button class="settings-row" data-view="${v}"><span>${i}</span><b>${l}<small>${d}</small></b><i>›</i></button>`).join('')}</section></div><button class="signout-link" data-action="signout">Sign out</button></div>`, 'more',{title:'Settings'})}
function printersView(){const list=state.allPrinters.length?state.allPrinters:state.printers;return page(`<div class="section-heading admin-heading"><div><h2>Printers</h2><p class="muted">Configure LAN or USB TSPL printing.</p></div><button data-action="add-printer">+ Add</button></div><section class="settings-card printer-list">${list.length?list.map(p=>`<button class="printer-list-row" data-printer="${p.id}"><span class="status-orb ${p.enabled?'':'off'}"></span><span><b>${esc(p.name)}</b><small>${esc(p.model)} · ${esc(p.driver)}</small><small>${p.driver==='TscTsplUsb'?`USB · ${esc(p.usbQueueName||'Queue not selected')}`:`${esc(p.ipAddress)}:${p.tcpPort}`} · ${p.dpi} DPI · ${p.labelWidthMm}×${p.labelHeightMm} mm</small></span><i>›</i></button>`).join(''):`<div class="empty"><b>No printers configured</b></div>`}</section>`, 'more',{title:'Printer Setup',back:true})}
function printerFormView(){const p=state.editingPrinter||{name:'Kitchen Printer',model:'TSC TE210',driver:'TscTsplNetwork',ipAddress:'',tcpPort:9100,dpi:203,labelWidthMm:50,labelHeightMm:30,mediaSensingMode:'Gap',gapMm:2,printMethod:'DirectThermal',printSpeedIps:3,printDensity:8,enabled:true};return page(`<form id="printerForm" class="admin-form"><section class="form-section"><h3>1. Printer identity</h3><label class="field"><span>Printer Name</span><input name="name" value="${esc(p.name)}" required></label><label class="field"><span>Printer Model</span><input name="model" value="${esc(p.model)}" placeholder="TSC TE210" required></label><label class="field"><span>Printer Driver</span><select name="driver"><option value="TscTsplNetwork" ${p.driver==='TscTsplNetwork'?'selected':''}>TSC TSPL Network</option><option value="Fake" ${p.driver==='Fake'?'selected':''}>Fake / Simulated</option></select></label></section><section class="form-section"><div class="form-title-row"><h3>2. Network</h3><button type="button" class="scan-button" data-action="scan-printers">⌁ Scan LAN</button></div><label class="field"><span>IP Address</span><input id="printerIp" name="ipAddress" value="${esc(p.ipAddress)}" inputmode="decimal" placeholder="Select from scan or enter manually" required></label><label class="field"><span>TCP Port</span><input id="printerPort" name="tcpPort" type="number" min="1" max="65535" value="${p.tcpPort}" required></label><div id="scanResults">${scanResults()}</div><p class="field-help">The server scans its LAN, the connecting user's private /24, and any configured discovery networks.</p></section><section class="form-section"><h3>3. Sticker roll</h3><div class="label-presets"><button type="button" data-label-preset="50,30,2">50 × 30</button><button type="button" data-label-preset="50,25,2">50 × 25</button><button type="button" data-label-preset="40,30,2">40 × 30</button></div><label class="field"><span>Resolution</span><select name="dpi"><option value="203" ${p.dpi===203?'selected':''}>203 DPI — TE200 / TE210</option><option value="300" ${p.dpi===300?'selected':''}>300 DPI — TE300 / TE310</option></select></label><div class="field-pair"><label class="field"><span>Sticker width (mm)</span><input id="labelWidth" name="labelWidthMm" type="number" min="20" max="108" step="0.1" value="${p.labelWidthMm}" required></label><label class="field"><span>Sticker height (mm)</span><input id="labelHeight" name="labelHeightMm" type="number" min="10" step="0.1" value="${p.labelHeightMm}" required></label></div><label class="field"><span>How labels are separated</span><select id="mediaMode" name="mediaSensingMode"><option value="Gap" ${p.mediaSensingMode==='Gap'?'selected':''}>Gap between stickers</option><option value="BlackMark" ${p.mediaSensingMode==='BlackMark'?'selected':''}>Black mark on backing</option><option value="Continuous" ${p.mediaSensingMode==='Continuous'?'selected':''}>Continuous roll</option></select></label><label class="field"><span>Gap / black-mark size (mm)</span><input id="gapSize" name="gapMm" type="number" min="0" step="0.1" value="${p.gapMm??2}"></label><label class="field"><span>Print material</span><select name="printMethod"><option value="DirectThermal" ${p.printMethod==='DirectThermal'?'selected':''}>Direct thermal — no ribbon</option><option value="ThermalTransfer" ${p.printMethod==='ThermalTransfer'?'selected':''}>Thermal transfer — ribbon installed</option></select></label><details class="advanced"><summary>Advanced print quality</summary><div class="field-pair"><label class="field"><span>Speed (ips)</span><input name="printSpeedIps" type="number" min="1" max="6" step="0.5" value="${p.printSpeedIps??3}"></label><label class="field"><span>Density (0–15)</span><input name="printDensity" type="number" min="0" max="15" value="${p.printDensity??8}"></label></div></details><div class="media-summary"><b>Current stock</b><span id="mediaSummary">${p.labelWidthMm} × ${p.labelHeightMm} mm · ${esc(p.mediaSensingMode||'Gap')} ${p.gapMm??2} mm · ${p.dpi} DPI</span></div><p class="calibration-tip"><b>After changing rolls:</b> calibrate the printer's gap/black-mark sensor using its FEED-button procedure or TSC Console, then run Test Print.</p><label class="toggle-row"><span><b>Enabled</b><small>Available for kitchen printing</small></span><input name="enabled" type="checkbox" ${p.enabled?'checked':''}></label></section><button class="btn btn-primary btn-block" type="submit">Save Printer</button>${state.editingPrinter?`<div class="test-actions"><button class="btn btn-outline" type="button" data-action="test-connection" data-id="${p.id}">Test Connection</button><button class="btn btn-soft" type="button" data-action="test-specific-print" data-id="${p.id}">Test Print</button></div>`:''}</form>`, 'more',{title:state.editingPrinter?'Edit Printer':'Add Printer',back:true})}
function scanResults(){if(!state.printerCandidates.length)return state.printerNetworks.length?`<div class="scan-empty">No device accepted a connection on this port in ${state.printerNetworks.map(esc).join(', ')}.</div>`:'';return`<div class="scan-results"><small>Possible raw-print devices</small>${state.printerCandidates.map(x=>`<button type="button" data-printer-ip="${esc(x.ipAddress)}" data-printer-port="${x.port}"><span><b>${esc(x.ipAddress)}</b><small>${esc(x.network)} · ${x.responseTimeMs} ms</small></span><i>Use this IP</i></button>`).join('')}</div>`}
function storageView(){const matches=l=>state.storageGroup==='Chillers'?/chiller/i.test(l.name):state.storageGroup==='Freezers'?/freezer/i.test(l.name):/dry/i.test(l.name),source=state.allLocations.length?state.allLocations:state.locations,locations=source.filter(matches),selected=locations.find(x=>x.id===state.selectedLocation)||locations[0],stored=selected?state.labels.filter(x=>x.storageLocation===selected.name&&x.status==='Active'):[];return page(`<div class="segmented">${['Chillers','Freezers','Dry Store'].map(g=>`<button class="${state.storageGroup===g?'active':''}" data-storage-group="${g}">${g}</button>`).join('')}</div><section class="settings-card storage-list">${locations.length?locations.map(l=>`<button class="settings-row ${selected?.id===l.id?'selected':''} ${l.active?'':'location-disabled'}" data-location="${l.id}"><span>${/freezer|chiller/i.test(l.name)?'❄':'▦'}</span><b>${esc(l.name)}${l.active?'':'<small>Disabled</small>'}</b><i>${state.labels.filter(x=>x.storageLocation===l.name&&x.status==='Active').length} items ›</i></button>`).join(''):`<div class="empty"><b>No ${esc(state.storageGroup.toLowerCase())} configured</b></div>`}</section>${selected?`<section class="storage-location-control"><div><b>${esc(selected.name)}</b><small>${selected.active?'Available for new labels and printing.':'Hidden from item defaults and new print jobs.'}</small></div><button class="btn ${selected.active?'btn-danger':'btn-outline'}" data-action="toggle-location" data-id="${selected.id}" data-active="${selected.active}">${selected.active?'Disable location':'Enable location'}</button></section><section class="storage-contents"><h3><span>Items in ${esc(selected.name)}</span><span>${stored.length}</span></h3>${stored.length?stored.map(x=>`<article class="storage-item"><span class="food-thumb food-photo ${photoFor(x.itemName)}"></span><div><b>${esc(x.itemName)}</b><small>Use by ${date(x.expiryDateTime)} · ${time(x.expiryDateTime)}</small></div></article>`).join(''):`<div class="empty"><b>No active labels here</b><small>${selected.active?'Printed labels assigned here will appear automatically.':'This location is disabled for future printing.'}</small></div>`}</section>`:''}`, 'more',{title:'Storage Locations',back:true})}
function itemAdminView(){return page(`<div class="admin-page item-admin"><div class="admin-toolbar"><div><small>${state.items.length} active items</small><h2>Item master</h2></div><div class="admin-toolbar-actions"><button class="btn btn-soft" data-action="batch-print">▤ Batch print</button><button class="btn btn-primary" data-action="add-item">+ Add item</button></div></div><label class="admin-search"><span>⌕</span><input id="itemAdminSearch" placeholder="Search items, categories or storage" autocomplete="off"></label><div class="item-master"><div class="item-master-head"><span>Item</span><span>Classification</span><span>Shelf life</span><span>Storage</span><span></span></div><div id="itemAdminList">${state.items.length?state.items.map(x=>`<button class="item-master-row" data-edit-item="${x.id}"><span class="item-identity"><span class="food-thumb food-photo large ${photoClass(x)}"${photoStyle(x)}></span><span><b>${esc(x.name)}</b><small>${esc(x.category||'Uncategorized')}</small></span></span><span><i class="class-badge ${x.classification==='Veg'?'veg':x.classification==='NonVeg'?'non-veg':'other'}">${classificationLabel(x.classification)}</i></span><span class="rule-cell"><b>${x.shelfLifeValue} ${esc(x.shelfLifeUnit)}</b><small>${esc(x.dateTerminology)}</small></span><span class="storage-cell">${esc(x.storage||'Not assigned')}</span><span class="row-chevron">›</span></button>`).join(''):`<div class="empty tall"><b>No items configured</b></div>`}</div></div></div>`, 'more',{title:'Manage Items',back:true})}
function batchPrintView(){const printer=preferredPrinter(),categories=[...new Set(state.items.map(x=>x.category).filter(Boolean))].sort((a,b)=>a.localeCompare(b));return page(`<form id="batchPrintForm" class="batch-print-page"><div class="batch-print-head"><div><small>QUICK PRINT ORDER</small><h1>Select items and quantities</h1></div><label class="field"><span>Printer</span><select id="batchPrinter" required>${state.printers.map(p=>`<option value="${p.id}" ${p.id===printer?.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label></div><div class="batch-filterbar"><label class="batch-search"><span>⌕</span><input id="batchSearch" type="search" placeholder="Filter items or category" autocomplete="off"></label><select id="batchCategoryFilter" aria-label="Filter by category"><option value="">All categories</option>${categories.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('')}</select><button type="button" class="btn btn-soft" data-action="batch-select-visible">Select all</button><button type="button" class="btn btn-outline" data-action="batch-clear">Clear</button></div><div class="batch-table"><div class="batch-table-head"><span>Select</span><span>Item</span><span>Storage</span><span>Labels</span></div>${state.items.map(x=>`<div class="batch-row" data-batch-row data-category="${esc(x.category||'')}" data-search="${esc(`${x.name} ${x.category||''} ${x.storage||''}`).toLowerCase()}"><label class="batch-check"><input type="checkbox" name="item" value="${x.id}" aria-label="Select ${esc(x.name)}"><span></span></label><div class="batch-item"><span class="food-thumb food-photo ${photoClass(x)}"${photoStyle(x)}></span><span><b>${esc(x.name)}</b><small>${esc(x.category)}</small></span></div><select class="batch-storage" aria-label="Storage for ${esc(x.name)}">${storageOptions(x)}</select><input class="batch-qty" type="number" min="1" max="10" value="1" inputmode="numeric" aria-label="Label quantity for ${esc(x.name)}"></div>`).join('')}<div id="batchEmpty" class="empty batch-empty" hidden><b>No items match this filter</b><small>Clear the filter or select another category.</small></div></div><div class="batch-order-bar"><span><b id="batchItemCount">0 items selected</b><small id="batchLabelCount">0 labels in this order</small></span><button type="submit" class="btn btn-primary" disabled>▣ Print order</button></div></form>`, 'items',{title:'Batch Print',back:true,className:'batch-print-screen'})}
function addItemView(){const x=state.editingItem||{name:'',categoryId:'',classification:'NonVeg',dateTerminology:'PREPARED',shelfLifeValue:1,shelfLifeUnit:'Days',defaultStorageLocationId:''},imageDataUrl=state.itemImageDraft===undefined?x.imageDataUrl:state.itemImageDraft,imageItem={name:x.name,imageDataUrl},selected=(a,b)=>a===b?'selected':'',checked=v=>x.classification===v?'checked':'';return page(`<form id="addItemForm" class="admin-form"><div class="item-image-editor"><div id="itemImagePreview" class="photo-placeholder food-photo ${photoClass(imageItem)}"${photoStyle(imageItem)}><span>▣</span><small>Item identification image</small></div><div class="image-actions"><label class="btn btn-soft image-picker">Change image<input id="itemImageInput" type="file" accept="image/jpeg,image/png,image/webp"></label>${imageDataUrl?'<button class="btn btn-outline" type="button" data-action="remove-item-image">Remove</button>':''}</div></div><label class="field"><span>Item Name</span><input name="name" value="${esc(x.name)}" placeholder="e.g. Chicken Pakora" required></label><label class="field"><span>Category</span><select id="itemCategorySelect" name="categoryId" required><option value="">Select Category</option>${state.categories.map(c=>`<option value="${c.id}" ${selected(x.categoryId,c.id)}>${esc(c.name)}</option>`).join('')}<option value="__new__">＋ Add new category…</option></select></label><div id="newCategoryRow" class="inline-create-row" hidden><input id="newCategoryName" type="text" maxlength="80" placeholder="Enter category name" autocomplete="off"><button class="btn btn-soft" type="button" data-action="save-new-category">Add category</button></div><fieldset><legend>Classification</legend><div class="choice-row"><label><input type="radio" name="classification" value="Veg" ${checked('Veg')} required><span class="classification-dot veg"></span><b>Veg</b></label><label><input type="radio" name="classification" value="NonVeg" ${checked('NonVeg')}><span class="classification-dot non-veg"></span><b>Non-Veg</b></label><label><input type="radio" name="classification" value="NotApplicable" ${checked('NotApplicable')}><span class="classification-dot other"></span><b>Other</b></label></div></fieldset><label class="field"><span>Date terminology</span><select id="itemDateTerminology" name="dateTerminology">${['PREPARED','CUT ON','OPENED','THAWED ON','RECEIVED','PACKED ON'].map(v=>`<option ${selected(x.dateTerminology,v)}>${v}</option>`).join('')}</select></label><div class="field-pair"><label class="field"><span>Shelf-life value</span><input id="shelfLifeValue" name="shelfLifeValue" type="number" min="1" max="9999" value="${x.shelfLifeValue}" required></label><label class="field"><span>Unit</span><select id="shelfLifeUnit" name="shelfLifeUnit">${['Minutes','Hours','Days','Weeks','Months'].map(v=>`<option ${selected(x.shelfLifeUnit,v)}>${v}</option>`).join('')}</select></label></div><div class="shelf-preview"><small>Automatic label dates</small><div><span id="shelfStartLabel">${esc(x.dateTerminology)}</span><b id="shelfStartValue"></b></div><div><span>USE BY</span><b id="shelfExpiryValue"></b></div><p>The backend recalculates this securely when the label is printed.</p></div><label class="field"><span>Default storage</span><select name="defaultStorageLocationId" required><option value="">Select Storage</option>${state.locations.map(l=>`<option value="${l.id}" ${selected(x.defaultStorageLocationId,l.id)}>${esc(l.name)}</option>`).join('')}</select></label><button class="btn btn-primary btn-block" type="submit">${state.editingItem?'Save Item':'Save Item'}</button></form>`, 'more',{title:state.editingItem?'Edit Item':'Add Item',back:true})}
function usersView(){const active=state.users.filter(x=>x.active).length;return page(`<div class="admin-page users-admin"><div class="admin-toolbar"><div><small>${active} active · ${state.users.length} total</small><h2>Team access</h2></div><button class="btn btn-primary" data-action="add-user">+ Add user</button></div>${state.userFormOpen?`<form id="userForm" class="user-create-panel"><div class="panel-heading"><div><small>New account</small><h2>Add user</h2></div><button type="button" class="icon-close" data-action="cancel-user" aria-label="Close">×</button></div><div class="user-form-grid"><label class="field"><span>Display name</span><input name="displayName" autocomplete="name" required></label><label class="field"><span>Role</span><select name="role"><option value="KitchenStaff">Kitchen Staff</option><option value="Supervisor">Supervisor</option><option value="Administrator">Administrator</option></select></label><label class="field"><span>PIN</span><input name="pin" type="password" inputmode="numeric" minlength="4" maxlength="12" autocomplete="new-password" required></label><button class="btn btn-primary" type="submit">Create user</button></div></form>`:''}<section class="user-directory"><div class="user-directory-head"><span>User</span><span>Role</span><span>Status</span><span></span></div>${state.users.length?state.users.map(u=>`<div class="user-management-row ${u.active?'':'disabled'}"><span class="user-identity"><i>${esc(u.displayName.trim().charAt(0).toUpperCase()||'U')}</i><span><b>${esc(u.displayName)}</b><small>${u.id===state.user?.id?'Signed in now':'Kitchen account'}</small></span></span><span class="role-label">${esc(u.role.replace(/([a-z])([A-Z])/g,'$1 $2'))}</span><span class="user-status ${u.active?'active':'inactive'}">${u.active?'Active':'Disabled'}</span><button class="btn ${u.active?'btn-soft':'btn-outline'} user-toggle" data-action="toggle-user" data-id="${u.id}" data-active="${u.active}" ${u.id===state.user?.id?'disabled':''}>${u.id===state.user?.id?'Current user':u.active?'Disable':'Enable'}</button></div>`).join(''):`<div class="empty tall"><b>No users available</b><small>Administrator access is required to manage users.</small></div>`}</section></div>`,'more',{title:'Users',back:true})}
function bridgeView(){const devices=state.bridgeDevices;const paired=state.bridgePairing;return page(`<div class="simple-page bridge-page"><section class="settings-card bridge-pair"><div class="panel-heading"><div><small>One-time secure setup</small><h2>Connect your printer</h2></div><button class="btn btn-primary" data-action="create-bridge-code">${paired?'New code':'Generate code'}</button></div>${paired?`<div class="pairing-code"><small>Enter this code in the KIVRA Print Bridge app</small><b>${esc(paired.code)}</b><span>Expires ${time(paired.expiresAt)}</span></div>`:`<p class="bridge-help">Install the bridge on the computer physically connected to the printer. Pairing is required only once.</p>`}<div class="panel-actions"><a class="btn btn-primary" href="/downloads/KIVRA-Windows-Print-Bridge.zip" download>Windows</a><a class="btn btn-soft" href="/downloads/KIVRA-Mac-Print-Bridge-Apple-Silicon.zip" download>Mac Apple Silicon</a><a class="btn btn-soft" href="/downloads/KIVRA-Mac-Print-Bridge-Intel.zip" download>Mac Intel</a></div><ol class="bridge-steps"><li>Connect and switch on the printer.</li><li>Download and open the bridge for this computer.</li><li>Generate and enter the six-digit code. This is required only once.</li><li>The bridge starts automatically at sign-in and reconnects after restarts.</li></ol></section><section class="settings-card bridge-devices"><div class="panel-heading"><div><small>Local agents</small><h2>Paired devices</h2></div><button class="icon-btn refresh-bridge" data-action="refresh-bridges" title="Refresh" aria-label="Refresh devices">↻</button></div>${devices.length?devices.map(x=>`<div class="bridge-device"><span class="status-orb ${x.online?'':'off'}"></span><span><b>${esc(x.name)}</b><small>${x.online?'Online now':x.lastSeenAt?`Last seen ${dt(x.lastSeenAt)}`:'Not yet connected'}${x.appVersion?` · v${esc(x.appVersion)}`:''}</small></span><button class="btn btn-soft" data-action="revoke-bridge" data-id="${x.id}">Revoke</button></div>`).join(''):`<div class="empty"><b>No print bridge paired</b><small>Generate a code to connect this computer.</small></div>`}</section></div>`,'more',{title:'Print Bridge',back:true})}
function reportsView(){return page(`<div class="simple-page"><h2>Reports & CSV</h2><p class="muted">Export the complete food-label history for spreadsheet analysis and compliance records.</p><div class="report-actions"><button class="btn btn-primary" data-action="download-report">Download label report (CSV)</button></div></div>`,'more',{title:'Reports & CSV',back:true})}
function aboutView(){return page(`<div class="simple-page"><section class="settings-card about-card"><img class="about-logo" src="/assets/kivra-routes-logo.webp" alt="KIVRA by Routes"><p class="about-copy">Kitchen label, expiry and printer management.<br><br>Designed for local-first operation on restaurant LANs.</p><button class="btn btn-soft about-storage-check" data-action="check-storage">Check data storage</button></section></div>`,'more',{title:'About KIVRA',back:true})}
function dataErrorView(){return page(`<div class="simple-page"><h2>Data source unavailable</h2><p class="muted">${esc(state.dataError||'The application could not load database records.')}</p><div class="report-actions"><button class="btn btn-primary" data-action="retry-data-load">Retry loading data</button><button class="btn btn-outline" data-action="signout">Sign out</button></div></div>`,'more',{title:'Data error'})}
function render(){if(state.dataError)app.innerHTML=dataErrorView();else if(state.view==='home')app.innerHTML=home();else if(state.view==='category')app.innerHTML=categoryView();else if(state.view==='print')app.innerHTML=printView();else if(state.view==='preview')app.innerHTML=previewView();else if(state.view==='success')app.innerHTML=successView(state.result);else if(state.view==='expiry')app.innerHTML=expiryView();else if(state.view==='history')app.innerHTML=historyView();else if(state.view==='label-detail')app.innerHTML=labelDetailView();else if(state.view==='storage')app.innerHTML=storageView();else if(state.view==='items')app.innerHTML=itemAdminView();else if(state.view==='batch-print')app.innerHTML=batchPrintView();else if(state.view==='add-item')app.innerHTML=addItemView();else if(state.view==='printers')app.innerHTML=printersView();else if(state.view==='printer-form')app.innerHTML=printerFormView();else if(state.view==='users')app.innerHTML=usersView();else if(state.view==='bridge')app.innerHTML=bridgeView();else if(state.view==='reports')app.innerHTML=reportsView();else if(state.view==='about')app.innerHTML=aboutView();else app.innerHTML=moreView();bindDynamic()}
function bindDynamic(){document.querySelector('#homeSearch')?.addEventListener('input',e=>{const q=e.target.value.trim();if(!q)return;state.category=null;state.view='category';render();requestAnimationFrame(()=>{const input=document.querySelector('#listSearch');if(!input)return;input.value=q;filterItems(q);input.focus();input.setSelectionRange(q.length,q.length)})});document.querySelector('#listSearch')?.addEventListener('input',e=>filterItems(e.target.value));document.querySelector('#itemAdminSearch')?.addEventListener('input',e=>filterAdminItems(e.target.value));document.querySelector('#historySearch')?.addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('.history-row').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(q))});document.querySelector('#batchPrintForm')?.addEventListener('submit',executeBatchPrint);document.querySelector('#batchPrintForm')?.addEventListener('input',e=>{if(e.target.id==='batchSearch')filterBatchRows();else updateBatchSummary()});document.querySelector('#batchPrintForm')?.addEventListener('change',e=>{if(e.target.id==='batchCategoryFilter')filterBatchRows();else updateBatchSummary()});document.querySelector('#userForm')?.addEventListener('submit',saveUser);document.querySelector('#itemImageInput')?.addEventListener('change',handleItemImage);document.querySelector('#itemCategorySelect')?.addEventListener('change',toggleNewCategory);document.querySelector('#newCategoryName')?.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();saveNewCategory()}});['shelfLifeValue','shelfLifeUnit','itemDateTerminology'].forEach(id=>document.querySelector(`#${id}`)?.addEventListener('input',updateShelfPreview));updateShelfPreview();document.querySelector('#printerForm')?.addEventListener('submit',savePrinter);['labelWidth','labelHeight','mediaMode','gapSize'].forEach(id=>document.querySelector(`#${id}`)?.addEventListener('input',updateMediaSummary));document.querySelector('[name="dpi"]')?.addEventListener('change',updateMediaSummary);enhanceUsbSetup()}
function updateShelfPreview(){const value=Number(document.querySelector('#shelfLifeValue')?.value),unit=document.querySelector('#shelfLifeUnit')?.value,terminology=document.querySelector('#itemDateTerminology')?.value,start=operationalNow();if(!unit||!Number.isFinite(value))return;const expiry=calculatePreview(start,value,unit),startEl=document.querySelector('#shelfStartValue'),expiryEl=document.querySelector('#shelfExpiryValue'),labelEl=document.querySelector('#shelfStartLabel');if(startEl)startEl.textContent=`${date(start)} · ${time(start)}`;if(expiryEl)expiryEl.textContent=`${date(expiry)} · ${time(expiry)}`;if(labelEl)labelEl.textContent=terminology}
function enhanceUsbSetup(){const form=document.querySelector('#printerForm'),driver=form?.querySelector('[name="driver"]');if(!driver)return;if(!driver.querySelector('[value="AndroidBridge"]'))driver.insertAdjacentHTML('afterbegin','<option value="AndroidBridge">Android Print Bridge</option>');if(!driver.querySelector('[value="TscTsplUsb"]'))driver.insertAdjacentHTML('beforeend','<option value="TscTsplUsb">TSC TSPL USB</option><option value="EpsonEscPosUsb">Epson receipt USB (test layout)</option>');driver.value=state.editingPrinter?.driver||'AndroidBridge';const port=document.querySelector('#printerPort')?.closest('.field');if(port&&!document.querySelector('#usbSetup'))port.insertAdjacentHTML('afterend',`<div id="usbSetup"><div class="form-title-row"><h3>USB queue</h3><button type="button" class="scan-button" data-action="scan-usb">⌁ Find USB</button></div><label class="field"><span>Server printer queue</span><select id="usbQueue" name="usbQueueName"><option value="">Select a connected USB printer</option>${usbQueueOptions()}</select></label><p class="field-help">USB means the printer is plugged into a locally hosted KIVRA server.</p></div>`);const update=()=>{const usb=driver.value==='TscTsplUsb'||driver.value==='EpsonEscPosUsb',lan=driver.value==='TscTsplNetwork',bridge=driver.value==='AndroidBridge',network=lan||bridge;document.querySelector('#usbSetup').hidden=!usb;document.querySelector('#printerIp').closest('.field').hidden=!network;document.querySelector('#printerPort').closest('.field').hidden=!network;document.querySelector('[data-action="scan-printers"]').hidden=!lan;document.querySelector('#scanResults').hidden=!lan;document.querySelector('#printerIp').required=network;document.querySelector('#usbQueue').required=usb;const help=document.querySelector('#scanResults')?.nextElementSibling;if(help&&bridge)help.textContent='Enter the printer LAN address. The bridge phone must be on the same Wi-Fi.'};driver.addEventListener('change',update);update()}
function usbQueueOptions(){const selected=state.editingPrinter?.usbQueueName||'',suggested=location.hostname==='localhost'||location.hostname==='127.0.0.1'?'':'TSC TA220';const queues=[...new Set([selected,suggested,...state.usbQueues].filter(Boolean))];return queues.map(x=>`<option value="${esc(x)}" ${x===selected?'selected':''}>${esc(x)}</option>`).join('')}
function filterItems(q){document.querySelectorAll('.category-item-row').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(q.toLowerCase()))}
function homeSearchScore(item,query){const q=query.trim().toLowerCase(),name=(item.name||'').toLowerCase(),category=(item.category||'').toLowerCase(),storage=(item.storage||'').toLowerCase(),terms=q.split(/\s+/).filter(Boolean),haystack=`${name} ${category} ${storage}`;if(!terms.every(term=>haystack.includes(term)))return-1;if(name===q)return100;if(name.startsWith(q))return90;if(name.split(/\s+/).some(word=>word.startsWith(q)))return75;if(name.includes(q))return60;if(category.includes(q))return35;if(storage.includes(q))return20;return10}
function renderHomeSearch(query){let panel=document.querySelector('#homeSearchResults');const search=document.querySelector('#homeSearch')?.closest('.search');if(!search)return;if(!panel){panel=document.createElement('div');panel.id='homeSearchResults';panel.className='home-search-results';search.insertAdjacentElement('afterend',panel)}const q=query.trim();if(!q){panel.hidden=true;panel.innerHTML='';return}const matches=state.items.map(item=>({item,score:homeSearchScore(item,q)})).filter(x=>x.score>=0).sort((a,b)=>b.score-a.score||a.item.name.localeCompare(b.item.name)).slice(0,8);panel.hidden=false;panel.innerHTML=matches.length?`<small class="search-result-count">${matches.length}${state.items.length>matches.length?' best':''} result${matches.length===1?'':'s'}</small>${matches.map(({item})=>`<button type="button" class="home-search-result" data-item="${item.id}"><span class="food-thumb food-photo ${photoClass(item)}"${photoStyle(item)}></span><span><b>${esc(item.name)}</b><small>${esc(item.category||'Uncategorized')} · ${esc(item.storage||'No storage')}</small></span><strong>${item.shelfLifeValue} ${esc(item.shelfLifeUnit)}</strong><i>›</i></button>`).join('')}`:`<div class="home-search-empty"><b>No matching items</b><small>Try the item name, category, or storage location.</small></div>`}
app.addEventListener('input',e=>{const id=e.target.id,query=e.target.value;if(id==='listSearch'){filterItems(query);return}if(id==='itemAdminSearch'){filterAdminItems(query);return}if(id==='historySearch'){const value=query.trim().toLowerCase();document.querySelectorAll('.history-row').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(value))}},{capture:true});
app.addEventListener('keydown',e=>{if(e.target.id==='homeSearch'&&e.key==='Escape'){e.target.value='';renderHomeSearch('');e.target.blur()}},{capture:true});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.querySelector('#homeSearch')?.focus()}});
function filterAdminItems(q){const value=q.trim().toLowerCase();document.querySelectorAll('.item-master-row').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(value))}
app.addEventListener('click',e=>{const card=e.target.closest('[data-expiry-filter]');if(!card)return;e.preventDefault();e.stopImmediatePropagation();if(card.dataset.expiryFilter==='all'&&expiryFilter==='all'){state.view='history';render();return}expiryFilter=card.dataset.expiryFilter;render()},{capture:true});
app.addEventListener('click',e=>{const row=e.target.closest('.item-master-row[data-edit-item]');if(!row)return;e.preventDefault();e.stopImmediatePropagation();const selected=state.items.find(x=>x.id===row.dataset.editItem);if(!selected){showToast('This item could not be opened. Refresh and try again.','error');return}state.editingItem=selected;state.itemImageDraft=selected.imageDataUrl||null;state.view='add-item';render()},{capture:true});
app.addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(action==='batch-print'){e.preventDefault();e.stopImmediatePropagation();state.view='batch-print';render();return}if(action==='batch-select-visible'){e.preventDefault();e.stopImmediatePropagation();selectBatchVisible();return}if(action==='batch-clear'){e.preventDefault();e.stopImmediatePropagation();clearBatchSelection();return}if(action==='back'&&state.view==='batch-print'){e.preventDefault();e.stopImmediatePropagation();state.view='items';render()}},{capture:true});
app.addEventListener('click',e=>{if(state.view!=='batch-print')return;if(e.target.closest('#batchPrintForm input, #batchPrintForm select, #batchPrintForm label, #batchPrintForm button'))e.stopImmediatePropagation()},{capture:true});
async function refreshBridgeDevices(){try{state.bridgeDevices=await request('/api/bridge/devices');if(state.view==='bridge')render()}catch(err){showToast(err.message,'error')}}
async function createBridgeCode(button){button.disabled=true;try{state.bridgePairing=await request('/api/bridge/pairing-code',{method:'POST'});await refreshBridgeDevices();showToast('Pairing code ready.','success')}catch(err){showToast(err.message,'error')}finally{button.disabled=false}}
async function revokeBridge(button){if(!confirm('Revoke this bridge phone? It will stop receiving print jobs.'))return;button.disabled=true;try{await request(`/api/bridge/devices/${button.dataset.id}`,{method:'DELETE'});await refreshBridgeDevices();showToast('Print bridge revoked.','success')}catch(err){showToast(err.message,'error');button.disabled=false}}
app.addEventListener('click',e=>{const view=e.target.closest('[data-view]')?.dataset.view,action=e.target.closest('[data-action]')?.dataset.action;if(view==='bridge')setTimeout(refreshBridgeDevices,0);if(action==='create-bridge-code')createBridgeCode(e.target.closest('button'));if(action==='refresh-bridges')refreshBridgeDevices();if(action==='revoke-bridge')revokeBridge(e.target.closest('button'))},{capture:true});
app.addEventListener('click',e=>{const button=e.target.closest('[data-action="check-storage"]');if(button)checkStorage(button)});
app.addEventListener('click',async e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(action==='add-item-to-category'){e.stopImmediatePropagation();let category=state.categories.find(c=>categoryKey(c.name)===categoryKey(state.category));try{if(!category){category=await request('/api/categories',{method:'POST',body:JSON.stringify({name:state.category,active:true})});state.categories.push(category)}state.editingItem=null;state.itemImageDraft=null;state.itemReturnCategory=category.name;state.view='add-item';render();const select=document.querySelector('#itemCategorySelect');if(select)select.value=category.id}catch(err){showToast(err.message,'error')}}else if(action==='back'&&state.view==='add-item'&&state.itemReturnCategory){e.stopImmediatePropagation();state.category=state.itemReturnCategory;state.itemReturnCategory=null;state.itemImageDraft=undefined;state.view='category';render()}},{capture:true});
app.addEventListener('click',async e=>{if(state.view==='batch-print'&&e.target.closest('#batchPrintForm'))return;const view=e.target.closest('[data-view]')?.dataset.view,action=e.target.closest('[data-action]')?.dataset.action,item=e.target.closest('[data-item]')?.dataset.item,editItem=e.target.closest('[data-edit-item]')?.dataset.editItem,labelId=e.target.closest('[data-label]')?.dataset.label,labelStatus=e.target.closest('[data-label-status]')?.dataset.labelStatus,storageGroup=e.target.closest('[data-storage-group]')?.dataset.storageGroup,category=e.target.closest('[data-category]')?.dataset.category,printerId=e.target.closest('[data-printer]')?.dataset.printer,candidate=e.target.closest('[data-printer-ip]'),preset=e.target.closest('[data-label-preset]')?.dataset.labelPreset,locationId=e.target.closest('[data-location]')?.dataset.location;if(action==='retry-data-load'){try{await hydrate()}catch(err){state.dataError=err.message;render()}return}if(view){try{if(view==='printers')state.allPrinters=await request('/api/printers/all');if(view==='users'){state.users=await request('/api/users');state.userFormOpen=false}if(view==='storage')state.allLocations=await request('/api/storage-locations/all')}catch(err){showToast(err.message,'error')}state.view=view;render();return}if(editItem){state.editingItem=state.items.find(x=>x.id===editItem);state.itemImageDraft=state.editingItem?.imageDataUrl||null;state.view='add-item';render();return}if(storageGroup){state.storageGroup=storageGroup;state.selectedLocation=null;render();return}if(locationId){state.selectedLocation=locationId;render();return}if(labelId){state.selectedLabel=state.labels.find(x=>x.id===labelId)||state.expiry.find(x=>x.id===labelId);state.view='label-detail';render();return}if(labelStatus){await changeLabelStatus(labelStatus);return}if(preset){const[w,h,g]=preset.split(',');document.querySelector('#labelWidth').value=w;document.querySelector('#labelHeight').value=h;document.querySelector('#gapSize').value=g;document.querySelector('#mediaMode').value='Gap';updateMediaSummary();return}if(candidate){document.querySelector('#printerIp').value=candidate.dataset.printerIp;document.querySelector('#printerPort').value=candidate.dataset.printerPort;showToast(`Selected ${candidate.dataset.printerIp}. Save and test the connection.`);return}if(printerId){state.editingPrinter=state.allPrinters.find(x=>x.id===printerId);state.view='printer-form';render();return}if(category){state.category=category;state.view='category';render();return}if(item){state.selected=state.items.find(x=>x.id===item);state.view='print';render();return}if(action==='back'){state.itemImageDraft=undefined;state.userFormOpen=false;state.view=state.view==='category'?'home':state.view==='print'?'category':state.view==='preview'?'print':state.view==='label-detail'?'history':state.view==='add-item'?'items':state.view==='printer-form'?'printers':'more';render()}else if(action==='back-to-print'){state.view='print';render()}else if(action==='add-user'){state.userFormOpen=true;render()}else if(action==='cancel-user'){state.userFormOpen=false;render()}else if(action==='toggle-user')await toggleUser(e.target.closest('[data-id]'));else if(action==='add-item'){state.editingItem=null;state.itemImageDraft=null;state.view='add-item';render()}else if(action==='save-new-category')await saveNewCategory(e.target.closest('button'));else if(action==='remove-item-image'){state.itemImageDraft=null;render()}else if(action==='toggle-location')await toggleStorageLocation(e.target.closest('[data-id]'));else if(action==='add-printer'){state.editingPrinter=null;state.printerCandidates=[];state.printerNetworks=[];state.usbQueues=[];state.view='printer-form';render()}else if(action==='scan-printers')await scanPrinters(e.target.closest('button'));else if(action==='scan-usb')await scanUsb(e.target.closest('button'));else if(action==='minus'||action==='plus'){const out=document.querySelector('#copies');out.value=Math.max(1,Math.min(10,Number(out.value)+(action==='plus'?1:-1)))}else if(action==='preview'){state.previewStorage=document.querySelector('#storageSelect')?.selectedOptions[0]?.text||state.selected?.storage;state.previewPrinter=state.printers.find(p=>p.id===document.querySelector('#printerSelect')?.value)||state.printers[0]||null;state.view='preview';render()}else if(action==='print')await printLabel();else if(action==='print-another'){state.view='category';render()}else if(action==='reprint-label')await reprintLabel();else if(action==='notifications')showToast(`${state.expiry.length} active expiry notification${state.expiry.length===1?'':'s'} available.`);else if(action==='download-report')await downloadReport();else if(action==='test-print')await testPrint();else if(action==='test-connection')await testPrinter(action,e.target.closest('[data-id]').dataset.id,false);else if(action==='test-specific-print')await testPrinter(action,e.target.closest('[data-id]').dataset.id,true);else if(action==='signout')signOut()});
async function printLabel(){if(state.busy)return;const p=document.querySelector('#printerSelect'),s=document.querySelector('#storageSelect'),copies=Number(document.querySelector('#copies')?.value||1);if(!p?.value){showToast('Configure an enabled printer first.','error');return}if(!s?.value){showToast('Select an active storage location before printing.','error');return}state.busy=true;const button=document.querySelector('[data-action="print"]');button.disabled=true;button.textContent='Sending to printer…';try{let result;for(let i=0;i<copies;i++)result=await request('/api/labels/print',{method:'POST',body:JSON.stringify({itemId:state.selected.id,printerId:p.value,requestedByUserId:'00000000-0000-0000-0000-000000000000',storageLocationId:s.value,operationalDateTime:null,quantity:null,unit:null,idempotencyKey:newIdempotencyKey()})});if(!['Printed','Queued'].includes(result.status))throw Error(result.failureReason||'Printer did not accept the label');result.printerName=p.selectedOptions[0]?.text;state.result=result;state.view='success';render();hydrate().catch(err=>showToast(err.message,'error'))}catch(err){showToast(err.message,'error');button.disabled=false;button.textContent='▣   PRINT LABEL'}finally{state.busy=false}}
function batchOrder(){return[...document.querySelectorAll('[data-batch-row]')].filter(row=>row.querySelector('[name="item"]').checked).map(row=>({itemId:row.querySelector('[name="item"]').value,storageLocationId:row.querySelector('.batch-storage').value,quantity:Math.max(1,Math.min(10,Number(row.querySelector('.batch-qty').value)||1))}))}
function batchVisibleRows(){return[...document.querySelectorAll('[data-batch-row]')].filter(row=>!row.hidden)}
function filterBatchRows(){const query=document.querySelector('#batchSearch')?.value.trim().toLowerCase()||'',category=document.querySelector('#batchCategoryFilter')?.value||'';let visible=0;document.querySelectorAll('[data-batch-row]').forEach(row=>{const matchesQuery=!query||row.dataset.search.includes(query),matchesCategory=!category||row.dataset.category===category;row.hidden=!(matchesQuery&&matchesCategory);if(!row.hidden)visible++});const empty=document.querySelector('#batchEmpty');if(empty)empty.hidden=visible>0;updateBatchSummary()}
function selectBatchVisible(){const rows=batchVisibleRows();rows.forEach(row=>row.querySelector('[name="item"]').checked=true);updateBatchSummary();showToast(`${rows.length} visible item${rows.length===1?'':'s'} selected.`,'success')}
function clearBatchSelection(){document.querySelectorAll('[data-batch-row] [name="item"]').forEach(input=>input.checked=false);updateBatchSummary();showToast('Batch selection cleared.','success')}
function updateBatchSummary(){const order=batchOrder(),labels=order.reduce((sum,x)=>sum+x.quantity,0),visible=batchVisibleRows().length,items=document.querySelector('#batchItemCount'),count=document.querySelector('#batchLabelCount'),button=document.querySelector('#batchPrintForm [type="submit"]');if(items)items.textContent=`${order.length} item${order.length===1?'':'s'} selected`;if(count)count.textContent=`${labels} label${labels===1?'':'s'} in this order · ${visible} visible`;if(button)button.disabled=!order.length||!document.querySelector('#batchPrinter')?.value}
async function executeBatchPrint(e){e.preventDefault();if(state.busy)return;const order=batchOrder(),printerId=document.querySelector('#batchPrinter')?.value,total=order.reduce((sum,x)=>sum+x.quantity,0),button=e.currentTarget.querySelector('[type="submit"]');if(!order.length)return showToast('Select at least one item.','error');if(!printerId)return showToast('Select a printer.','error');if(order.some(x=>!x.storageLocationId))return showToast('Select storage for every item.','error');if(total>100)return showToast('A print order can contain up to 100 labels.','error');state.busy=true;button.disabled=true;let completed=0;try{for(const line of order)for(let copy=0;copy<line.quantity;copy++){button.textContent=`Printing ${completed+1} of ${total}...`;const result=await request('/api/labels/print',{method:'POST',body:JSON.stringify({itemId:line.itemId,printerId,requestedByUserId:'00000000-0000-0000-0000-000000000000',storageLocationId:line.storageLocationId,operationalDateTime:null,quantity:null,unit:null,idempotencyKey:newIdempotencyKey()})});if(!['Printed','Queued'].includes(result.status))throw Error(result.failureReason||'Printer did not accept the label');completed++}await hydrate();state.view='history';render();showToast(`${completed} labels sent in one print order.`,'success')}catch(err){showToast(`${completed} of ${total} labels sent. ${err.message}`,'error');button.disabled=false;button.textContent='▣ Print order'}finally{state.busy=false}}
async function downloadReport(){try{const response=await fetch('/api/reports/labels.csv',{headers:{Authorization:`Bearer ${state.token}`}});if(!response.ok)throw Error(response.status===403?'Supervisor or Administrator access is required.':'Could not generate the report.');const url=URL.createObjectURL(await response.blob()),link=document.createElement('a');link.href=url;link.download='kivra-label-report.csv';link.click();URL.revokeObjectURL(url);showToast('CSV report downloaded.','success')}catch(err){showToast(err.message,'error')}}
async function reprintLabel(){if(!state.selectedLabel)return;try{const id=state.selectedLabel.id,result=await request(`/api/labels/${id}/reprint`,{method:'POST',body:JSON.stringify({idempotencyKey:newIdempotencyKey()})});if(!['Printed','Queued'].includes(result.status))throw Error(result.failureReason||'Reprint failed.');showToast(result.status==='Queued'?'Reprint queued for the Android bridge.':'Existing label reprinted successfully.','success');await hydrate();state.selectedLabel=state.labels.find(x=>x.id===id);state.view='label-detail';render()}catch(err){showToast(err.message,'error')}}
async function changeLabelStatus(status){if(!state.selectedLabel)return;try{await request(`/api/labels/${state.selectedLabel.id}/status`,{method:'PATCH',body:JSON.stringify({status})});showToast(`Label marked ${status.toLowerCase()}.`,'success');await hydrate();state.view='history';render()}catch(err){showToast(err.message,'error')}}
async function toggleStorageLocation(button){const active=button.dataset.active==='true',name=state.allLocations.find(x=>x.id===button.dataset.id)?.name||'this location';if(active&&!confirm(`Disable ${name}? It will be removed from new item and print selections.`))return;button.disabled=true;try{await request(`/api/storage-locations/${button.dataset.id}/active`,{method:'PATCH',body:JSON.stringify({active:!active})});const[activeLocations,allLocations]=await Promise.all([request('/api/storage-locations'),request('/api/storage-locations/all')]);state.locations=activeLocations;state.allLocations=allLocations;showToast(`${name} ${active?'disabled':'enabled'}.`,'success');render()}catch(err){showToast(err.message,'error');button.disabled=false}}
async function saveUser(e){e.preventDefault();const form=new FormData(e.currentTarget),button=e.currentTarget.querySelector('[type="submit"]');button.disabled=true;try{await request('/api/users',{method:'POST',body:JSON.stringify({displayName:form.get('displayName'),role:form.get('role'),pin:form.get('pin')})});state.users=await request('/api/users');state.userFormOpen=false;showToast('User created.','success');render()}catch(err){showToast(err.message,'error');button.disabled=false}}
async function toggleUser(button){const active=button.dataset.active==='true',user=state.users.find(x=>x.id===button.dataset.id);if(!user||user.id===state.user?.id)return;if(active&&!confirm(`Disable ${user.displayName}? They will no longer be able to sign in.`))return;button.disabled=true;try{await request(`/api/users/${user.id}/active`,{method:'PATCH',body:JSON.stringify({active:!active})});state.users=await request('/api/users');showToast(`${user.displayName} ${active?'disabled':'enabled'}.`,'success');render()}catch(err){showToast(err.message,'error');button.disabled=false}}
async function testPrint(){const p=preferredPrinter();if(!p)return showToast('No printer configured.','error');try{const r=await request(`/api/printers/${p.id}/test-print`,{method:'POST'});showToast(r.success?'Test label sent successfully.':r.error,r.success?'success':'error')}catch(err){showToast(err.message,'error')}}
async function testPrinter(_,id,print){try{const r=await request(`/api/printers/${id}/${print?'test-print':'test-connection'}`,{method:'POST'});showToast(r.success?(print?'Test label sent successfully.':'Printer connection succeeded.'):r.error,r.success?'success':'error')}catch(err){showToast(err.message,'error')}}
async function checkStorage(button){button.disabled=true;try{const result=await request('/api/system/storage');showToast(`Data storage verified: ${result.items} items, ${result.labels} labels, ${result.printJobs} print jobs.`,'success')}catch(err){showToast(err.message||'Could not verify data storage.','error')}finally{button.disabled=false}}
async function scanPrinters(button){const port=Number(document.querySelector('#printerPort')?.value||9100);button.disabled=true;button.textContent='Scanning…';try{const result=await request(`/api/printers/discover?port=${port}`);state.printerCandidates=result.candidates;state.printerNetworks=result.networks;document.querySelector('#scanResults').innerHTML=scanResults();showToast(result.candidates.length?`Found ${result.candidates.length} possible printer${result.candidates.length===1?'':'s'}.`:'No raw-print devices found.',result.candidates.length?'success':'error')}catch(err){showToast(err.message,'error')}finally{button.disabled=false;button.textContent='⌁ Scan LAN'}}
async function scanUsb(button){button.disabled=true;button.textContent='Searching…';try{const result=await request('/api/printers/discover-usb');state.usbQueues=result.queues;const select=document.querySelector('#usbQueue'),current=select.value;select.innerHTML=`<option value="">Select a connected USB printer</option>${usbQueueOptions()}`;if(current)select.value=current;if(result.bridgeRequired)showToast('Cloud printing uses KIVRA Windows Print Bridge. Select TSC TA220 and keep the bridge running.','success');else showToast(result.queues.length?`Found ${result.queues.length} server printer queue${result.queues.length===1?'':'s'}.`:'No USB printer queues found.',result.queues.length?'success':'error')}catch(err){showToast(err.message,'error')}finally{button.disabled=false;button.textContent='⌁ Find USB'}}
function updateMediaSummary(){const w=document.querySelector('#labelWidth')?.value,h=document.querySelector('#labelHeight')?.value,m=document.querySelector('#mediaMode')?.value,g=document.querySelector('#gapSize')?.value,d=document.querySelector('[name="dpi"]')?.value;const el=document.querySelector('#mediaSummary');if(el)el.textContent=`${w} × ${h} mm · ${m}${m==='Continuous'?'':` ${g} mm`} · ${d} DPI`}
async function savePrinter(e){e.preventDefault();const form=new FormData(e.currentTarget),button=e.currentTarget.querySelector('button[type="submit"]');button.disabled=true;const payload={name:form.get('name'),model:form.get('model'),driver:form.get('driver'),ipAddress:form.get('ipAddress')||'',tcpPort:Number(form.get('tcpPort')||9100),usbQueueName:form.get('usbQueueName')||null,dpi:Number(form.get('dpi')),labelWidthMm:Number(form.get('labelWidthMm')),labelHeightMm:Number(form.get('labelHeightMm')),mediaSensingMode:form.get('mediaSensingMode'),gapMm:Number(form.get('gapMm')),printMethod:form.get('printMethod'),printSpeedIps:Number(form.get('printSpeedIps')),printDensity:Number(form.get('printDensity')),enabled:form.get('enabled')==='on'};try{const editing=state.editingPrinter;await request(editing?`/api/printers/${editing.id}`:'/api/printers',{method:editing?'PUT':'POST',body:JSON.stringify(payload)});showToast(editing?'Printer updated.':'Printer added.','success');state.allPrinters=await request('/api/printers/all');state.printers=state.allPrinters.filter(x=>x.enabled);state.view='printers';render()}catch(err){showToast(err.message,'error');button.disabled=false}}
async function handleItemImage(e){const file=e.target.files?.[0];if(!file)return;if(!/^image\/(jpeg|png|webp)$/.test(file.type)){showToast('Choose a JPEG, PNG, or WebP image.','error');return}try{state.itemImageDraft=await resizeItemImage(file);const preview=document.querySelector('#itemImagePreview');preview.className='photo-placeholder food-photo custom-photo';preview.style.backgroundImage=`url('${state.itemImageDraft}')`;showToast('Image ready. Save the item to keep it.','success')}catch{showToast('That image could not be opened. Try a JPEG or PNG.','error')}}
function resizeItemImage(file){return new Promise((resolve,reject)=>{const img=new Image(),url=URL.createObjectURL(file);img.onload=()=>{const max=1000,scale=Math.min(1,max/Math.max(img.naturalWidth,img.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);URL.revokeObjectURL(url);resolve(canvas.toDataURL('image/webp',.78))};img.onerror=()=>{URL.revokeObjectURL(url);reject()};img.src=url})}
function toggleNewCategory(e){const adding=e.target.value==='__new__',row=document.querySelector('#newCategoryRow'),input=document.querySelector('#newCategoryName');if(row)row.hidden=!adding;if(adding)setTimeout(()=>input?.focus(),0)}
async function saveNewCategory(button){const input=document.querySelector('#newCategoryName'),select=document.querySelector('#itemCategorySelect'),name=input?.value.trim();if(!name){showToast('Enter a category name.','error');input?.focus();return}const existing=state.categories.find(c=>c.name.trim().toLowerCase()===name.toLowerCase());if(existing){select.value=existing.id;document.querySelector('#newCategoryRow').hidden=true;showToast('That category already exists and has been selected.');return}const oldText=button?.textContent;if(button){button.disabled=true;button.textContent='Adding...'}try{const category=await request('/api/categories',{method:'POST',body:JSON.stringify({name,active:true})});state.categories.push(category);state.categories.sort((a,b)=>a.name.localeCompare(b.name));const option=document.createElement('option');option.value=category.id;option.textContent=category.name;select.insertBefore(option,select.querySelector('option[value="__new__"]'));select.value=category.id;document.querySelector('#newCategoryRow').hidden=true;input.value='';showToast(`${category.name} added and selected.`,'success')}catch(err){showToast(err.message,'error')}finally{if(button){button.disabled=false;button.textContent=oldText}}}
async function saveItem(e){e.preventDefault();const element=e.target,form=new FormData(element),button=element.querySelector('button[type="submit"]'),buttonText=button.textContent,editing=state.editingItem,categoryId=form.get('categoryId');if(!categoryId||categoryId==='__new__'){showToast('Select a category or add the new category first.','error');document.querySelector('#itemCategorySelect')?.focus();return}const payload={name:form.get('name')?.trim(),shortName:null,imageDataUrl:state.itemImageDraft??null,categoryId,classification:form.get('classification'),labelType:'Food',dateTerminology:form.get('dateTerminology'),shelfLifeValue:Number(form.get('shelfLifeValue')),shelfLifeUnit:form.get('shelfLifeUnit'),defaultStorageLocationId:form.get('defaultStorageLocationId')||null,defaultLabelTemplate:'standard-50x30',active:true};button.disabled=true;button.textContent='Saving...';try{await request(editing?`/api/items/${editing.id}`:'/api/items',{method:editing?'PUT':'POST',body:JSON.stringify(payload)});const returnCategory=!editing?state.itemReturnCategory:null;state.editingItem=null;state.itemImageDraft=undefined;state.itemReturnCategory=null;if(returnCategory){state.category=returnCategory;state.view='category'}else state.view='items';await hydrate();showToast(editing?'Item updated and saved.':returnCategory?`Item saved in ${returnCategory}.`:'Item saved to the database.','success')}catch(err){showToast(err.message,'error');button.disabled=false;button.textContent=buttonText}}
function showToast(message,type='success'){const toast=document.querySelector('#toast');toast.textContent=message;toast.className=`toast show ${type}`;setTimeout(()=>toast.className='toast',3500)}
function signOut(){state.token='';state.user=null;sessionStorage.removeItem('kivraToken');sessionStorage.removeItem('kivraUser');sessionStorage.removeItem('kivraBootstrap');document.querySelector('#loginDialog').showModal()}
function normalizeItemStorageField(){const select=app.querySelector('#addItemForm select[name="defaultStorageLocationId"]');if(!select||select.dataset.normalized==='true')return;select.dataset.normalized='true';select.required=false;const empty=select.querySelector('option[value=""]');if(empty){empty.disabled=false;if(empty.textContent!=='No default storage')empty.textContent='No default storage'}const activeIds=new Set(state.locations.filter(x=>x.active!==false).map(x=>x.id));select.querySelectorAll('option:not([value=""])').forEach(option=>{if(!activeIds.has(option.value))option.remove()})}
new MutationObserver(normalizeItemStorageField).observe(app,{childList:true,subtree:true});
app.addEventListener('submit',e=>{if(e.target.id==='addItemForm')saveItem(e)});
document.querySelector('#loginForm').addEventListener('submit',async e=>{e.preventDefault();const error=document.querySelector('#loginError');error.hidden=true;try{const result=await request('/api/auth/pin',{method:'POST',body:JSON.stringify({pin:document.querySelector('#pin').value})});state.token=result.token;state.user=result.user;sessionStorage.kivraToken=result.token;sessionStorage.kivraUser=JSON.stringify(result.user);document.querySelector('#loginDialog').close();try{await hydrate()}catch(loadErr){state.dataError=loadErr.message;sessionStorage.removeItem('kivraBootstrap');render()}}catch(err){error.textContent=err.message==='Unauthorized'?'Incorrect PIN. Please try again.':err.message;error.hidden=false}});
async function start(){if(!state.token){document.querySelector('#loginDialog').showModal();return}render();try{await hydrate()}catch(err){state.dataError=err.message;sessionStorage.removeItem('kivraBootstrap');render()}}
if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js');start();
